@push('scripts')<script>document.addEventListener('change',async e=>{const input=e.target.closest('.return-receipt, input[name="refund_receipt"]');if(!input)return;const form=input.closest('form'),message=form.querySelector('.return-scan-message,.payout-scan-message'),reference=form.querySelector('.return-reference,.payout-reference'),submit=form.querySelector('button[type="submit"]');reference.value='';submit.disabled=true;if(!input.files[0]){message.textContent='Select a receipt image to scan.';return;}message.textContent='Scanning receipt…';message.className='small mt-1 text-muted';const body=new FormData();body.append(input.name,input.files[0]);try{const response=await fetch(input.dataset.scanUrl,{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||'','Accept':'application/json'},body}),data=await response.json();if(!response.ok||!data.ok){message.textContent=(data.errors||[data.error||'Receipt verification failed.']).join(' ');message.className='small mt-1 text-danger';return;}reference.value=data.reference_number||'';submit.disabled=!reference.value;message.textContent='Receipt verified. Reference number was scanned automatically.';message.className='small mt-1 text-success';}catch(_){message.textContent='Receipt scan is unavailable. Please try again.';message.className='small mt-1 text-danger';}});</script>@endpush
